import {themeToggle,enhanceScene} from './appearance.js';
import {money,analyze,scoreCandidate} from './engine.js';
import {api,streamAgent} from './local-client.js';
const $=s=>document.querySelector(s);const clone=v=>structuredClone(v);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',spark:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3Z',chart:'M4 19V5 M4 19h16 M8 15l4-5 4 2 4-7',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-3 3V11.5a10 10 0 0 1 20 0Z',insta:'M7 3h10a4 4 0 0 1 4 4v10a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V7a4 4 0 0 1 4-4Z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17.5 6.5h.01',plug:'m8 3 0 5 M16 3v5 M6 8h12v3a6 6 0 0 1-12 0V8Z M12 17v4',arrow:'M7 17 17 7 M7 7h10v10',right:'M5 12h14 m-5-5 5 5-5 5',down:'m6 9 6 6 6-6',chevron:'m9 5 7 7-7 7',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',upload:'M12 16V3 m-5 5 5-5 5 5 M3 15v6h18v-6',download:'M12 3v12 m-5-5 5 5 5-5 M3 17v4h18v-4',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',database:'M20 6c0 2-4 3-8 3S4 8 4 6s4-3 8-3 8 1 8 3Z M4 6v12c0 2 4 3 8 3s8-1 8-3V6 M4 12c0 2 4 3 8 3s8-1 8-3',file:'M14 2H4v20h16V8l-6-6Z M14 2v6h6 M8 13h8 M8 17h5',close:'m6 6 12 12 M6 18 18 6',send:'m3 3 18 9-18 9 4-9-4-9Z M7 12h14',wallet:'M3 6h16v15H3V6Z M3 6V3h13v3 M15 11h6v5h-6v-5Z',trend:'m3 17 6-6 4 4 8-10 M15 5h6v6',shield:'m12 3 9 4v5c0 6-9 10-9 10S3 18 3 12V7l9-4Z m-4 9 3 3 5-6',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',calendar:'M3 5h18v16H3V5Z M7 2v6 M17 2v6 M3 11h18',more:'M5 12h.01 M12 12h.01 M19 12h.01',logout:'M9 4H3v16h6 M10 12h11 m-4-4 4 4-4 4',brief:'M3 7h18v14H3V7Z M8 7V3h8v4 M3 12h18 M10 11v3h4v-3',refresh:'M20 7V3l-3 3a8 8 0 1 0 3 9 M20 3h-5',menu:'M3 6h18 M3 12h18 M3 18h18',stop:'M6 6h12v12H6z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const nav=[['dashboard','grid','Обзор бизнеса'],['agent','spark','AI-агент'],['analytics','chart','Аналитика и БД'],['hr','users','HR и команда'],['messages','chat','Коммуникации'],['smm','insta','Instagram SMM']];
let state={view:location.hash.slice(1)||'dashboard',rows:[],source:'Локальный источник не подключён',candidates:[],threads:[],selectedThread:'t1',plan:[],runs:[],shortlisted:[],paused:[],business:'Orbit Studio',autoDraft:true,period:'latest',messageDrafts:{}};
let local={status:'loading',config:null,errors:[],files:[],schema:null};
let busy=false,abortRun=false,activePrompt='',serverMode=false,queryFilter='',liveEvents=[],runController=null;
const save=()=>{}; // Local company data and tool observations remain in memory, not browser storage.
const current=()=>analyze(state.rows,state.period);const compact=n=>n>=1e6?(n/1e6).toFixed(2).replace('.',',')+' млн ₸':money(n);
const percent=n=>n.toFixed(1).replace('.',',')+'%';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function go(view){if(!nav.some(n=>n[0]===view)&&view!=='integrations')view='dashboard';state.view=view;location.hash=view;queryFilter='';render();window.scrollTo(0,0);}
function periodSelect(){return `<select aria-label="Период аналитики" id="period"><option value="latest" ${state.period==='latest'?'selected':''}>Последний месяц</option>${current().months.map(m=>`<option value="${m}" ${state.period===m?'selected':''}>${m}</option>`).join('')}<option value="all" ${state.period==='all'?'selected':''}>Все периоды</option></select>`;}
function render(){const name=nav.find(n=>n[0]===state.view)?.[2]||'Интеграции';$('#app').innerHTML=`
<aside class="sidebar"><a href="#dashboard" class="brand" aria-label="Orbit — на главную"><span class="brand-symbol"><i></i></span>orbit<span class="brand-dot">®</span></a>
<button class="workspace" data-action="business"><span class="workspace-logo">O<span>↗</span></span><span><strong>${esc(state.business)}</strong><small>Бизнес-пространство</small></span>${icon('down')}</button>
<div class="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav>${nav.map(([id,ic,label])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}">${icon(ic)}<span>${label}</span>${id==='agent'?'<span class="ai-badge">AI</span>':id==='messages'?`<span class="count">${state.threads.filter(t=>t.unread).length}</span>`:''}</button>`).join('')}</nav>
<div class="sidebar-bottom"><div class="autopilot-card"><span class="mini-orbit">✧</span><strong>Больше времени на главное</strong><p>Рутина под контролем.<br>Возможности — перед вами.</p><button data-view="agent">Поставить задачу ${icon('right')}</button></div><button class="nav-item ${state.view==='integrations'?'active':''}" data-view="integrations">${icon('plug')}<span>Интеграции</span><span class="dot green"></span></button><button class="nav-item" data-action="help">${icon('help')}<span>О демо-продукте</span></button><div class="profile"><div class="avatar owner">НМ</div><div><strong>Нурлан М.</strong><small>Владелец бизнеса</small></div><span class="pro">PRO</span></div></div></aside>
<div class="app-main"><header class="topbar"><div class="crumb"><button class="mobile-menu" aria-label="Открыть меню" data-action="menu">${icon('menu')}</button><span>Рабочее пространство</span>${icon('chevron')}<strong>${name}</strong></div><div class="top-actions"><span class="demo-label"><span class="dot"></span> ${serverMode?'Local workspace':'Local server required'}</span>${themeToggle()}<button class="icon-button" aria-label="Уведомления" data-action="notifications">${icon('bell')}<i></i></button><div class="avatar small">НМ</div></div></header>
<main id="main-content" class="content view-${state.view}">${connectionBanner()}${({dashboard,agent:agentPage,analytics,hr,messages,smm,integrations}[state.view]||dashboard)()}</main><footer class="page-footer"><span><span class="dot green"></span> ${serverMode?'SQLite / файлы · Read-only':'Запустите локальный сервер'}</span><span>Orbit Business OS <b>·</b> Local Agent v2.0</span></footer></div>`; bind();enhanceScene(state.view);}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metricCards(){const a=current();return `<div class="metrics">${[
 ['wallet','Выручка',compact(a.revenue),a.growth===null?'Нет сравнения':`${a.growth>=0?'+':''}${percent(a.growth)}`,'за период','lavender'],
 ['chart','Прибыль',compact(a.profit),percent(a.margin),'от выручки','mint'],
 ['trend','Маржинальность',percent(a.margin),a.margin>=35?'Выше цели':'Ниже цели','цель 35%','peach'],
 ['brief','Сделки',String(a.count),'За месяц','по базе данных','blue']
 ].map(([ic,label,value,delta,context,color])=>`<article class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ic)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom"><span class="change ${label==='Сделки'?'neutral':''}">${label==='Выручка'&&a.growth!==null?icon('trend'):''}${delta}</span><span>${context}</span></div></article>`).join('')}</div>`;}
function chartMarkup(a=current()){const w=680,h=216,pad=12;const points=a.series.length?a.series:[{date:'—',revenue:0,cost:0}];const max=Math.max(...points.map(p=>p.revenue),1)*1.2;const xy=key=>points.map((p,i)=>[44+i*(w-62)/Math.max(points.length-1,1),h-28-(p[key]/max)*(h-46)]);const rev=xy('revenue'),cost=xy('cost');const path=pts=>pts.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="График выручки и расходов за выбранный период"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b9a9ef" stop-opacity=".35"/><stop offset="1" stop-color="#b9a9ef" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(n=>{const y=h-28-n*(h-46);return `<line x1="44" y1="${y}" x2="${w-12}" y2="${y}" stroke="#e9ebef" stroke-dasharray="3 5"/><text x="0" y="${y+4}" fill="#9a9ca8" font-size="10">${Math.round(max*n/1000)}к</text>`;}).join('')}<path d="${path(rev)} L${rev.at(-1)[0]},${h-28} L44,${h-28} Z" fill="url(#area)"/><path d="${path(cost)}" fill="none" stroke="#b8c6b6" stroke-width="2" stroke-dasharray="5 5"/><path d="${path(rev)}" fill="none" stroke="#9682d2" stroke-width="2.5" stroke-linejoin="round"/>${points.map((p,i)=>i%Math.max(1,Math.floor(points.length/6))===0?`<text x="${rev[i][0]}" y="${h-4}" text-anchor="middle" fill="#9a9ca8" font-size="10">${esc(p.date.slice(8)||p.date)}</text>`:'').join('')}</svg></div>`;}
function chartCard(){const a=current();return `<section class="panel revenue-panel"><div class="panel-head"><div><h2>Динамика бизнеса</h2><p>Выручка и расходы · ${esc(a.month)}</p></div><span class="pill">${icon('calendar')} За период</span></div><div class="chart-summary"><strong>${compact(a.revenue)}</strong><div class="legend"><span><i style="background:#aa98dc"></i>Выручка</span><span><i style="background:#bccab8"></i>Расходы</span></div></div>${chartMarkup(a)}</section>`;}
function dashboard(){const a=current();return `${heading('ВАШ БИЗНЕС В ОДНОМ ОКНЕ','Всё под контролем<span class="heading-star">✳</span>','От данных к решениям. Ваш AI-агент уже на связи.',`${periodSelect()}<button class="btn" data-action="export">${icon('download')} Отчёт</button>`)}
<section class="agent-banner"><div class="banner-copy"><div class="banner-kicker"><span class="dot green"></span> ORBIT LOCAL INTELLIGENCE <span>READ-ONLY</span></div><h2>Вы задаёте направление.<br>Агент берёт на себя рутину.</h2><p>Анализируйте бизнес, развивайте команду и находите точки роста.</p><button class="btn dark" data-view="agent">${icon('spark')} Начать с AI-агентом ${icon('right')}</button></div><div class="orbit-art" aria-hidden="true"><div class="orb-glow"></div><div class="orbit-ring r1"></div><div class="orbit-ring r2"></div><div class="orb-traveler"><div class="orb">✧</div></div><span class="floating-chip chip-a">${icon('check')} Локальный контекст</span><span class="floating-chip chip-b">${icon('trend')} Новые возможности</span><i class="star s1">✦</i><i class="star s2">✦</i></div></section>
${metricCards()}<div class="dashboard-grid">${chartCard()}<section class="panel insight-panel"><div class="panel-head"><h2>${icon('spark')} В фокусе агента</h2><span class="tiny-label">DATA INSIGHT</span></div><div class="insight-visual"><span>↗</span><i></i><i></i><i></i><i></i></div><h3>У прибыли есть<br>потенциал роста</h3><p>«${esc(a.topCosts[0]?.[0]||'Расходы')}» — крупнейшая статья расходов за период. Проверьте её эффективность.</p><button class="text-button" data-prompt="Посчитай маржинальность за последний месяц и найди топ-3 затратных статьи">Разобрать с агентом ${icon('right')}</button></section></div>
<div class="dashboard-bottom"><section class="panel activity-panel"><div class="panel-head"><div><h2>Работа агента</h2><p>От поставленной задачи до готового результата</p></div><button class="text-button muted" data-view="agent">Все задачи ${icon('right')}</button></div><div class="task-table"><div class="table-head"><span>ЗАДАЧА</span><span>МОДУЛЬ</span><span>СТАТУС</span></div>${(state.runs.length?state.runs.slice(-3).reverse():[{title:'Анализ локальной базы',type:'analytics',seed:true},{title:'Скоринг локальных резюме',type:'hr',seed:true},{title:'Контент на основе продаж',type:'smm',seed:true}]).map((r,i)=>`<button class="task-row" data-${r.seed?'prompt':'run'}="${r.seed?esc(['Проанализируй финансовый отчёт за последний месяц','Оцени кандидатов','Создай контент-план'][i]):r.id}"><span><span class="task-icon ${['lavender','mint','peach'][i%3]}">${icon(r.type==='hr'?'users':r.type==='smm'?'insta':'chart')}</span>${esc(r.title)}</span><span>${({analytics:'Аналитика',hr:'HR',smm:'SMM',messages:'Продажи',help:'Агент',schema:'База',sql:'SQL',file:'Файлы',local:'Агент','file-list':'Файлы'})[r.type]||'Агент'}</span><span class="status ${r.seed?'waiting':'done'}">${r.seed?'Попробовать':icon('check')+'Готово'}</span></button>`).join('')}</div></section><section class="panel connections"><div class="panel-head"><h2>Интеграции</h2><button class="icon-button" aria-label="Настройки интеграций" data-view="integrations">${icon('arrow')}</button></div>${[['database','База данных',state.rows.length+' записей'],['chat','WhatsApp','Коммуникации'],['insta','Instagram','Контент и сообщения']].map(([ic,n,sub])=>`<button class="connection-row" data-view="integrations"><span class="connection-icon">${icon(ic)}</span><span><strong>${n}</strong><small>${sub}</small></span><span class="sim-label">${serverMode?'Local':'Offline'}</span></button>`).join('')}</section></div>`;}
function agentPage(){return `${heading('ORBIT INTELLIGENCE','Ваш бизнес-партнёр, 24/7','Поставьте задачу. Следите за выполнением. Получите результат.',`<span class="pill mint">${icon('shield')} ${serverMode?(local.config?.model?'Ollama · Local':'Local tools · SQL planner'):'Offline'}</span>`)}<div class="agent-layout"><section class="panel chat-panel"><div class="chat-top"><div class="agent-avatar">✧</div><div><strong>Orbit Agent</strong><small><span class="dot green"></span> ${serverMode?'Локальные инструменты подключены':'Ожидаю локальный сервер'}</small></div><button class="icon-button" aria-label="Новая задача" data-action="new-task">${icon('plus')}</button></div><div class="chat-history" id="chat-history" aria-live="polite">${state.runs.length?state.runs.slice(-8).map(r=>runMarkup(r)).join(''):`<div class="chat-welcome"><div class="welcome-symbol">✧</div><span class="eyebrow">МЕНЬШЕ РУТИНЫ. БОЛЬШЕ ВОЗМОЖНОСТЕЙ.</span><h2>Что сделаем для<br>вашего бизнеса сегодня?</h2><p>Я объединяю данные, команду и коммуникации,<br>чтобы вы могли сосредоточиться на росте.</p><div class="suggestions">${[['chart','Проанализировать прибыль','Посчитай маржинальность за последний месяц и найди топ-3 затратных статьи'],['users','Найти сильных кандидатов','Оцени кандидатов и дай рекомендации'],['insta','Спланировать контент','Создай контент-план на следующую неделю'],['chat','Подготовить ответы','Подготовь ответы клиентам WhatsApp']].map(([ic,t,p])=>`<button data-prompt="${p}">${icon(ic)}<span>${t}</span>${icon('arrow')}</button>`).join('')}</div></div>`}${busy?`<div class="user-message">${esc(activePrompt)}</div><div class="execution-live"><div class="agent-avatar">✧</div><div><strong>Выполняю задачу<span class="thinking-dots">...</span></strong><div class="execution-steps">${eventMarkup(liveEvents)}</div></div></div>`:''}</div><form id="agent-form" class="composer"><textarea id="prompt" rows="2" maxlength="2000" placeholder="Например: найди точки роста прибыли за последний месяц…" aria-label="Задача для AI-агента" ${busy?'disabled':''}></textarea><div class="composer-bottom"><span>${icon('database')} ${esc(state.source)} <b>·</b> ${state.rows.length} строк</span>${busy?`<button class="send-btn stop" type="button" data-action="stop" aria-label="Остановить задачу">${icon('stop')}</button>`:`<button class="send-btn" type="submit" aria-label="Выполнить задачу">${icon('right')}</button>`}</div></form><div class="composer-note">${serverMode?'Настоящие локальные вызовы · SQL только на чтение · без облачной передачи данных':'Требуется локальный Node.js + Python сервер. Облачная страница не читает ваш диск.'}</div></section><aside class="agent-context"><section class="panel"><div class="panel-head"><h2>Контекст бизнеса</h2>${icon('brief')}</div><div class="context-body"><div class="workspace-logo large">O↗</div><h3>${esc(state.business)}</h3><p>Консалтинг и автоматизация бизнеса</p><div class="context-line"><span>Источник данных</span><strong>${state.rows.length} записей</strong></div><div class="context-line"><span>Валюта</span><strong>KZT · ₸</strong></div><div class="context-line"><span>Режим</span><strong>Local read-only</strong></div></div></section><section class="panel tools-panel"><h2>Инструменты агента</h2>${[['database','Анализ данных'],['users','Оценка кандидатов'],['chat','Ответы клиентам'],['insta','Генерация контента']].map(([ic,n])=>`<div>${icon(ic)}${n}<span class="dot green"></span></div>`).join('')}</section><div class="context-tip">${icon('shield')}<p>Вы контролируете решения.<br>Агент готовит рекомендации и черновики для проверки.</p></div></aside></div>`;}
function runMarkup(r){return `<div class="user-message">${esc(r.prompt)}</div><article class="agent-response"><div class="response-avatar">✧</div><div class="response-content"><div class="response-name">Orbit Agent <span>Local · ${esc(r.time)}</span></div><details class="log-details"><summary>${icon('check')} Журнал выполнения · ${r.logs.length} ${icon('down')}</summary>${r.events?.length?eventMarkup(r.events):`<ol>${r.logs.map(l=>`<li>${esc(l)}</li>`).join('')}</ol>`}</details><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p>${r.type==='analytics'?`<div class="inline-metrics"><span>Выручка<strong>${compact(r.data.revenue)}</strong></span><span>Маржа<strong>${percent(r.data.margin)}</strong></span></div>${chartMarkup(r.data)}`:''}${r.type==='sql'?resultTable(r.data.rows):r.type==='file'&&r.data?.records?resultTable(r.data.records):''}<div class="response-actions">${['analytics','hr','smm','messages'].includes(r.type)?`<button class="btn small-btn" data-view="${r.type==='analytics'?'analytics':r.type==='hr'?'hr':r.type==='smm'?'smm':'messages'}">Открыть ${r.type==='analytics'?'аналитику':r.type==='hr'?'кандидатов':r.type==='smm'?'контент-план':'диалоги'} ${icon('right')}</button>`:''}<button class="text-button muted" data-export-run="${r.id}">${icon('download')} Отчёт</button></div></div></article>`;}
function analytics(){const a=current();return `${heading('ДАННЫЕ → РЕШЕНИЯ','Аналитика и база данных','Показатели, на которые можно опереться.',`<button class="btn" data-action="schema">${icon('database')} Схема и SQL</button><button class="btn dark" data-action="workspace">${icon('file')} Рабочая папка</button>`)}<div class="source-bar"><span class="source-icon">${icon('database')}</span><div><strong>${esc(state.source)}</strong><span>${state.rows.length} записей · ${a.months.length} периода · SQLite / CSV / JSON / XLSX</span></div><span class="pill mint">${icon('check')} Данные проверены</span>${periodSelect()}</div>${metricCards()}<div class="dashboard-grid">${chartCard()}<section class="panel cost-panel"><div class="panel-head"><h2>Топ-3 статьи расходов</h2>${icon('chart')}</div><div class="cost-total"><small>Всего расходов</small><strong>${compact(a.cost)}</strong></div>${a.topCosts.map(([n,v],i)=>`<div class="cost-row"><div><span><i style="background:${['#baa9e7','#bfd5bf','#eac8ad'][i]}"></i>${esc(n)}</span><strong>${money(v)}</strong></div><div class="progress"><i style="width:${a.cost?v/a.cost*100:0}%;background:${['#baa9e7','#bfd5bf','#eac8ad'][i]}"></i></div></div>`).join('')}<button class="text-button" data-prompt="Найди топ-3 затратных статьи и посчитай маржинальность">Получить рекомендации ${icon('right')}</button></section></div><section class="panel data-panel"><div class="panel-head"><div><h2>Исходные данные</h2><p>Первые 50 записей выбранного периода</p></div><button class="btn small-btn" data-action="export-data">${icon('download')} CSV</button></div><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Продукт</th><th>Канал</th><th>Выручка</th><th>Расходы</th><th>Статья затрат</th></tr></thead><tbody>${a.data.slice(0,50).map(r=>`<tr><td>${esc(r.date)}</td><td><strong>${esc(r.product)}</strong></td><td><span class="tag">${esc(r.channel)}</span></td><td>${money(r.revenue)}</td><td>${money(r.cost)}</td><td>${esc(r.category)}</td></tr>`).join('')||'<tr><td colspan="6">Нет записей за выбранный период.</td></tr>'}</tbody></table></div></section>`;}
function hr(){const candidates=state.candidates.map(scoreCandidate).sort((a,b)=>b.score-a.score).filter(c=>c.name.toLowerCase().includes(queryFilter.toLowerCase()));return `${heading('ЛЮДИ, КОТОРЫЕ ДВИГАЮТ БИЗНЕС','Сильная команда начинается здесь','Профессиональные навыки, прозрачный скоринг и решение за вами.',`<button class="btn dark" data-action="workspace">${icon('file')} Локальные резюме</button>`)}<div class="hr-summary"><div class="panel role-card"><span class="metric-icon lavender">${icon('brief')}</span><div><small>ОТКРЫТАЯ ВАКАНСИЯ</small><h2>Менеджер по продажам</h2><p>B2B · CRM · Переговоры · Аналитика · 5 лет опыта — максимум баллов</p></div><span class="pill mint">Открыта</span></div><div class="panel candidates-count"><strong>${state.candidates.length}</strong><span>кандидатов в базе</span></div><div class="panel candidates-count"><strong>${state.shortlisted.length}</strong><span>в шорт-листе</span></div></div><section class="panel"><div class="panel-head"><div><h2>Кандидаты</h2><p>70% — соответствие навыкам · 30% — опыт, до 5 лет</p></div><label class="search-field">${icon('search')}<input id="candidate-search" aria-label="Поиск кандидата" placeholder="Поиск по имени" value="${esc(queryFilter)}"></label></div><div class="candidate-grid">${candidates.map((c,i)=>`<article class="candidate-card"><div class="candidate-top"><div class="avatar candidate-avatar ${['lilac','mint','peach','blue'][i%4]}">${esc(c.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div class="score ${c.score>=80?'high':''}">${c.score}<small>/100</small></div></div><h3>${esc(c.name)}</h3><p>${esc(c.role)} · опыт: ${c.experience} г.</p><div class="skill-tags">${c.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="recommendation">${icon(c.score>=80?'check':'file')} ${esc(c.recommendation)}</div><button class="btn full" data-candidate="${esc(c.id)}">Смотреть резюме ${icon('right')}</button>${state.shortlisted.includes(c.id)?'<span class="shortlist-label">✓ В шорт-листе</span>':''}</article>`).join('')||'<div class="empty-state">Кандидаты не найдены.</div>'}</div></section><div class="info-note">${icon('shield')} Скоринг использует только указанные профессиональные навыки и опыт. Он помогает подготовить интервью; решение принимает HR.</div>`;}
function messages(){if(!state.threads.length)return `${heading('ЛОКАЛЬНЫЕ КОММУНИКАЦИИ','Диалоги из рабочей папки','Подключите JSON-файл диалогов в настройках.')}<section class="panel smm-empty"><h2>Источник сообщений не настроен</h2><p>Ответы готовятся локальным бэкендом. Отправка во внешние сервисы не подключена.</p><button class="btn dark" data-view="integrations">Настроить источник</button></section>`;const t=state.threads.find(t=>t.id===state.selectedThread)||state.threads[0];return `${heading('КАЖДЫЙ ДИАЛОГ — ВОЗМОЖНОСТЬ','Ближе к вашим клиентам','Локальный JSON → диалоги → серверный черновик ответа.',`<button class="btn" data-action="refresh-local">${icon('refresh')} Перечитать файл</button>`)}<div class="inbox panel"><aside class="thread-list"><div class="thread-heading"><h2>Входящие <span>${state.threads.length}</span></h2><span class="sim-label">Draft only</span></div>${state.threads.map(x=>`<button class="thread ${x.id===t.id?'selected':''}" data-thread="${x.id}"><span class="avatar ${x.channel==='Instagram'?'lilac':'mint'}">${esc(x.initials)}</span><span class="thread-copy"><strong>${esc(x.name)}<small>${esc(x.time)}</small></strong><span>${esc(x.messages.at(-1).text)}</span><em>${icon(x.channel==='Instagram'?'insta':'chat')}${x.channel}</em></span>${x.unread?'<i class="unread-dot"></i>':''}</button>`).join('')}</aside><section class="conversation"><div class="conversation-header"><div class="avatar mint">${esc(t.initials)}</div><div><strong>${esc(t.name)}</strong><small>${t.channel} · Локальный файл</small></div><span class="pill">Draft only</span></div><div class="message-history">${t.messages.map(m=>`<div class="bubble ${m.from==='agent'?'outgoing':''}"><p>${esc(m.text)}</p><small>${m.from==='agent'?'Локальный черновик · не отправлен':'Сообщение клиента'}</small></div>`).join('')}</div><div class="reply-area"><div class="reply-label"><span>${icon('spark')} Локальный черновик</span><button class="text-button" data-action="generate-reply">${icon('refresh')} Сгенерировать</button></div><textarea id="reply" rows="4" maxlength="4000" placeholder="Нажмите «Сгенерировать» или напишите свой ответ…" aria-label="Черновик ответа клиенту">${esc(state.messageDrafts[t.id]||'')}</textarea><div class="reply-bottom"><small>${icon('shield')} Внешняя отправка не подключена</small><button class="btn dark" data-action="send-reply">Сохранить в сессии ${icon('send')}</button></div></div></section></div>`;}
function smm(){return `${heading('ОТ БИЗНЕС-ДАННЫХ К КОНТЕНТУ','Контент с пониманием бизнеса','Темы, которые работают на ваши цели.',`<button class="btn" data-action="export-plan">${icon('download')} Экспорт</button><button class="btn dark" data-action="generate-plan">${icon('spark')} ${state.plan.length?'Обновить план':'Создать контент-план'}</button>`)}<div class="smm-banner"><div><span class="eyebrow">INSTAGRAM · ЛОКАЛЬНЫЕ ЧЕРНОВИКИ</span><h2>Хорошие идеи начинаются с данных.</h2><p>AI учитывает популярные продукты и финансовые показатели вашей базы.</p></div><div class="smm-symbol">${icon('insta')}</div></div>${state.plan.length?`<div class="section-label"><h2>Неделя с фокусом на рост</h2><span class="pill">19–23 октября 2026</span></div><div class="content-plan">${state.plan.map((p,i)=>`<article class="post-card ${p.color}"><div class="post-day"><strong>${esc(p.day)}</strong><span>${esc(p.date)}</span>${icon(p.type==='Reels'?'insta':'file')}</div><span class="post-type">${esc(p.type)}</span><div class="post-visual"><span>${['✳','↗','?','%','✧'][i]}</span><small>ORBIT<br>STUDIO</small></div><div class="post-content"><span class="pillar">${esc(p.pillar)}</span><h3>${esc(p.topic)}</h3><button class="text-button" data-post="${i}">Открыть черновик ${icon('arrow')}</button></div><div class="post-footer"><span class="dot"></span> ${p.approved?'Одобрен локально':'Черновик'}<span>12:00</span></div></article>`).join('')}</div><div class="info-note">${icon('database')} Основа плана: «${esc(current().products[0]?.[0]||'нет данных')}» — лидер по выручке. Публикации остаются черновиками.</div>`:`<section class="panel smm-empty"><div class="welcome-symbol">✳</div><h2>Ваша следующая неделя — уже почти готова</h2><p>Пять идей, разные форматы и тексты с учётом бизнес-аналитики.</p><button class="btn dark" data-action="generate-plan">${icon('spark')} Сгенерировать план</button></section>`}`;}
function integrations(){return `${heading('ВАШ КОМПЬЮТЕР → ВАШИ ДАННЫЕ','Локальные подключения','SQLite и файлы доступны только локальному бэкенду.',`<button class="btn dark" data-action="configure-local">${icon('plug')} Настроить подключение</button>`)}<div class="integration-grid">${[['database','SQLite','Read-only',local.config?.database||'Не выбрана'],['file','Рабочая папка','Local filesystem',local.config?.workspace||'Сервер не запущен'],['users','HR-источник','Local records',local.config?.hrFile||'Таблица candidates'],['spark','Планировщик',local.config?.model?'Ollama':'SQL planner',local.config?.model||'Встроенные инструменты без LLM']].map(([ic,n,sub,value])=>`<section class="panel integration-card"><div class="integration-top"><span class="integration-logo lavender">${icon(ic)}</span><span class="sim-label">${serverMode?'Connected':'Offline'}</span></div><h2>${n}</h2><small>${sub}</small><p class="path-value">${esc(value)}</p><button class="btn full" data-action="${ic==='database'?'schema':ic==='file'?'workspace':'configure-local'}">Открыть ${icon('right')}</button></section>`).join('')}</div><section class="panel settings-panel"><h2>Источники и инструменты</h2><div class="setting-row"><div><strong>Финансовый источник</strong><p>${esc(state.source)}</p></div><button class="btn" data-action="workspace">Выбрать файл</button></div><div class="setting-row"><div><strong>Диалоги WhatsApp / Instagram</strong><p>${esc(local.config?.messagesFile||'JSON-файл не выбран')} · только черновики, внешняя отправка не подключена</p></div><button class="btn" data-action="configure-local">Настроить</button></div><div class="setting-row"><div><strong>Перечитать данные с диска</strong><p>Обновить графики, кандидатов и диалоги из текущих источников</p></div><button class="btn" data-action="refresh-local">${icon('refresh')} Обновить</button></div><div class="setting-row"><div><strong>Очистить текущую сессию</strong><p>Убрать историю задач и черновики из памяти браузера</p></div><button class="btn" data-action="reset">Очистить сессию</button></div></section>`;}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function report(a=current()){return `# Orbit — Финансовый отчёт\n\nИсточник: ${state.source}\nПериод: ${a.month}\nЗаписей: ${a.count}\n\n| Показатель | Значение |\n|---|---|\n| Выручка | ${money(a.revenue)} |\n| Расходы | ${money(a.cost)} |\n| Прибыль | ${money(a.profit)} |\n| Маржинальность | ${percent(a.margin)} |\n\n## Топ затрат\n${a.topCosts.map(([n,v])=>`- ${n}: ${money(v)}`).join('\n')}\n\nРасчёт по локальному источнику.\n`;}
function requireIntegration(id){if(state.paused.includes(id)){toast('Симулятор приостановлен. Возобновите его в интеграциях.');return false;}return true;}
function modal(title,body,after){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-close aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;$('#modal-root').querySelector('[data-close]').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal();};after?.();setTimeout(()=>$('.modal input,.modal textarea,.modal button')?.focus(),0);}
function closeModal(){$('#modal-root').innerHTML='';}
function candidateModal(id){const c=scoreCandidate(state.candidates.find(c=>c.id===id));modal(esc(c.name),`<div class="resume-title"><span>${esc(c.role)}</span><strong>${c.score}<small>/100</small></strong></div><p class="resume-text">${esc(c.resume)}</p><h3>Почему такой балл</h3><p>Совпадение навыков: ${c.matched.length} из 4 (${Math.round(c.matched.length/4*70)} баллов). Опыт: ${c.experience} лет (${Math.round(Math.min(c.experience/5,1)*30)} баллов).</p><div class="skill-tags">${c.matched.map(s=>`<span>✓ ${esc(s)}</span>`).join('')}</div>${c.missing.length?`<p>Уточнить на интервью: ${esc(c.missing.join(', '))}.</p>`:'<p>Все ключевые навыки указаны в резюме.</p>'}<div class="info-note">${icon('shield')} Рекомендация: ${esc(c.recommendation)}. Окончательное решение принимает HR.</div><div class="modal-actions"><button class="btn" data-close-inner>Закрыть</button><button class="btn dark" id="shortlist">${state.shortlisted.includes(id)?'Убрать из шорт-листа':'Добавить в шорт-лист'}</button></div>`,()=>{$('[data-close-inner]').onclick=closeModal;$('#shortlist').onclick=()=>{if(!requireIntegration('hr'))return;state.shortlisted=state.shortlisted.includes(id)?state.shortlisted.filter(x=>x!==id):[...state.shortlisted,id];save();closeModal();render();toast('Шорт-лист обновлён.');};});}
function postModal(i){const p=state.plan[i];modal('Черновик публикации',`<div class="post-modal-meta"><span class="tag">${esc(p.type)}</span><span>${esc(p.date)} · 12:00</span><span class="sim-label">Draft only</span></div><label class="form-label">Тема<input id="post-topic" maxlength="200" value="${esc(p.topic)}"></label><label class="form-label">Текст публикации<textarea id="post-body" rows="10" maxlength="5000">${esc(p.body)}</textarea></label><div class="modal-actions"><button class="btn" id="copy-post">${icon('download')} Скачать текст</button><button class="btn dark" id="approve-post">${icon('check')} Одобрить черновик</button></div><p class="fine-print">Одобрение сохраняется в памяти текущей сессии. В Instagram ничего не публикуется.</p>`,()=>{$('#copy-post').onclick=()=>download(`orbit-post-${i+1}.txt`,$('#post-topic').value+'\n\n'+$('#post-body').value);$('#approve-post').onclick=()=>{if(!requireIntegration('ig'))return;if(!$('#post-topic').value.trim()||!$('#post-body').value.trim())return toast('Добавьте тему и текст.');p.topic=$('#post-topic').value.trim();p.body=$('#post-body').value.trim();p.approved=true;save();closeModal();render();toast('Черновик одобрен в текущей сессии.');};});}
async function execute(prompt){
 if(busy)return;if(!serverMode)return toast('Запустите локальный сервер: ./start.command');
 busy=true;abortRun=false;activePrompt=prompt;liveEvents=[];runController=new AbortController();go('agent');
 try{
  const result=await streamAgent({query:prompt,business:state.business},{signal:runController.signal,onStep:event=>{liveEvents.push(event);render();if($('#chat-history'))$('#chat-history').scrollTop=$('#chat-history').scrollHeight;}});
  if(result.type==='smm')state.plan=result.data;
  if(result.type==='hr')state.candidates=result.data;
  if(result.type==='analytics'){state.period=result.data.month==='Все периоды'?'all':result.data.month;const context=await api('/api/context');state.rows=context.rows;state.source=context.source;local.errors=context.errors;}
  state.runs.push({...result,id:crypto.randomUUID(),prompt,time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});state.runs=state.runs.slice(-20);
 }catch(e){const text=e.name==='AbortError'?'Задача остановлена.':e.message;state.runs.push({id:crypto.randomUUID(),type:'help',title:e.name==='AbortError'?'Задача остановлена':'Ошибка локального инструмента',prompt,text,events:liveEvents,logs:liveEvents.filter(e=>e.status==='completed').map(e=>e.label),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});toast(text);
 }finally{busy=false;runController=null;render();if($('#chat-history'))$('#chat-history').scrollTop=$('#chat-history').scrollHeight;}
}
const actions={
 'workspace':workspaceBrowser,'schema':schemaDialog,'configure-local':configureLocal,'refresh-local':()=>refreshLocal().catch(e=>toast(e.message)),
 'export':()=>download('orbit-financial-report.md',report(),'text/markdown;charset=utf-8'),
 'export-data':()=>{const cols=['date','product','revenue','cost','category','channel'];const csvCell=v=>'"'+String(v).replace(/"/g,'""')+'"';download('orbit-data.csv','\uFEFF'+cols.join(',')+'\n'+current().data.map(r=>cols.map(k=>csvCell(typeof r[k]==='string'&&/^[=+\-@]/.test(r[k])?"'"+r[k]:r[k])).join(',')).join('\n'),'text/csv;charset=utf-8');},
 'generate-plan':async()=>{try{const r=await api('/api/content-plan',{});state.plan=r.posts;render();toast('План рассчитан по локальным данным: '+r.source);}catch(e){toast(e.message);}},
 'export-plan':()=>{if(!state.plan.length)return toast('Сначала создайте контент-план.');download('orbit-content-plan.md','# Orbit — Контент-план\n\n'+state.plan.map(p=>`## ${p.date} · ${p.type}\n### ${p.topic}\n\n${p.body}\n\nСтатус: ${p.approved?'Одобрен локально':'Черновик'}\n`).join('\n'),'text/markdown;charset=utf-8');},
 'generate-reply':async()=>{try{const t=state.threads.find(t=>t.id===state.selectedThread);const r=await api('/api/reply',{threadId:t.id,business:state.business});state.messageDrafts[t.id]=r.draft;render();}catch(e){toast(e.message);}},
 'send-reply':()=>{const t=state.threads.find(t=>t.id===state.selectedThread);const text=$('#reply').value.trim();if(!text)return toast('Сначала подготовьте ответ.');t.messages.push({from:'agent',text});delete state.messageDrafts[t.id];render();toast('Черновик сохранён в сессии. Во внешние сервисы не отправлен.');},
 'business':()=>modal('Контекст бизнеса',`<form id="business-form"><label class="form-label">Название бизнеса<input id="business-name" maxlength="60" required value="${esc(state.business)}"></label><p class="fine-print">Название используется в локальных черновиках. Стоимость услуг нужно подтверждать по требованиям клиента.</p><div class="modal-actions"><button class="btn dark">Сохранить</button></div></form>`,()=>{$('#business-form').onsubmit=e=>{e.preventDefault();const v=$('#business-name').value.trim();if(!v)return;state.business=v;save();closeModal();render();toast('Контекст обновлён.');};}),
 'toggle-draft':()=>{state.autoDraft=!state.autoDraft;save();render();},
 'reset':()=>{state.runs=[];state.plan=[];state.messageDrafts={};state.shortlisted=[];refreshLocal().catch(e=>toast(e.message));toast('Сессия очищена. Файлы и база не изменялись.');},
 'new-task':()=>{$('#prompt')?.focus();toast('Введите новую задачу в поле ниже.');},
 'stop':()=>{abortRun=true;runController?.abort();},'menu':()=>$('.sidebar').classList.toggle('mobile-open'),
 'notifications':()=>modal('Локальный статус',`<p>${serverMode?'Локальный сервер подключён.':'Локальный сервер недоступен.'}</p><p>Источник: ${esc(state.source)}</p>${local.errors.map(e=>`<p>${esc(e)}</p>`).join('')}`),
 'help':()=>modal('Orbit Local Agent',`<div class="about-logo">orbit<span>✧</span></div><p>Инструменты читают настоящую SQLite-базу и файлы выбранной папки. SQL выполняется только на чтение. Журнал показывает фактические вызовы и ошибки.</p><p>Без LLM работает встроенный SQL-планировщик. Для свободных запросов подключите локальную Ollama-модель в интеграциях.</p><p>Ответы клиентам и SMM — серверные черновики на основе локального контекста. Внешняя отправка не подключена.</p>`)

};
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>execute(b.dataset.prompt));document.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>candidateModal(b.dataset.candidate));document.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>postModal(Number(b.dataset.post)));document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{state.selectedThread=b.dataset.thread;state.threads.find(t=>t.id===state.selectedThread).unread=false;save();render();});document.querySelectorAll('[data-toggle-integration]').forEach(b=>b.onclick=()=>{const id=b.dataset.toggleIntegration;state.paused=state.paused.includes(id)?state.paused.filter(x=>x!==id):[...state.paused,id];save();render();});document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>go('agent'));document.querySelectorAll('[data-export-run]').forEach(b=>b.onclick=()=>{const r=state.runs.find(x=>x.id===b.dataset.exportRun);download('orbit-task-report.md',`# ${r.title}\n\nЗапрос: ${r.prompt}\n\n${r.text}\n\n## Выполненные шаги\n${r.logs.map(l=>'- '+l).join('\n')}`,'text/markdown;charset=utf-8');});
 if($('#period'))$('#period').onchange=e=>{state.period=e.target.value;save();render();};
 if($('#agent-form')){$('#agent-form').onsubmit=e=>{e.preventDefault();const q=$('#prompt').value.trim();if(q)execute(q);};$('#prompt').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#agent-form').requestSubmit();}};}
 if($('#candidate-search'))$('#candidate-search').oninput=e=>{const start=e.target.selectionStart;queryFilter=e.target.value;render();$('#candidate-search').focus();$('#candidate-search').setSelectionRange(start,start);};
 if($('#reply'))$('#reply').oninput=e=>{state.messageDrafts[state.selectedThread]=e.target.value;save();};}
window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==state.view)go(location.hash.slice(1));});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const focusable=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
render();refreshLocal().catch(e=>{local.status='offline';local.errors=[e.message];render();});

// Local workspace presentation: file exploration, connection configuration and observable tools.
function connectionBanner(){
 if(local.status==='loading')return '<div class="local-banner">Подключаюсь к локальному серверу…</div>';
 if(!serverMode)return `<div class="local-banner error"><strong>Локальный сервер не подключён.</strong><span>Запустите ./start.command и откройте http://localhost:3000. Доступ к диску через публичную страницу не предоставляется.</span></div>`;
 return local.errors.length?`<div class="local-banner error"><strong>Проверьте локальные источники</strong>${local.errors.map(e=>`<span>${esc(e)}</span>`).join('')}<button class="text-button" data-action="configure-local">Настроить подключение ${icon('right')}</button></div>`:'';
}
async function refreshLocal(){
 const health=await api('/api/health');if(health.mode!=='local')throw Error('Нужен Orbit Local Agent v2. Запустите новую локальную версию.');
 const context=await api('/api/context');serverMode=true;local={...local,status:'connected',config:context.config,errors:context.errors};
 state.rows=context.rows;state.source=context.source;state.candidates=context.candidates;state.threads=context.threads;
 if(!state.threads.some(t=>t.id===state.selectedThread))state.selectedThread=state.threads[0]?.id||'';
 render();return context;
}
function eventMarkup(events){const visible=[];for(const e of events){if(e.callId){const idx=visible.findIndex(x=>x.id===e.callId);if(idx>=0){visible[idx]={...visible[idx],...e};continue;}}visible.push(e);}
 return visible.map(e=>`<div class="tool-event ${esc(e.status)}"><span>${icon(e.status==='error'?'close':e.status==='running'?'clock':'check')}<strong>${esc(e.label||e.name)}</strong>${e.name?`<code>${esc(e.name)}</code>`:''}${e.summary?`<small>${esc(e.summary)}</small>`:''}${e.elapsedMs!==undefined?`<small>${e.elapsedMs} ms</small>`:''}</span>${e.args?.query?`<pre>${esc(e.args.query)}</pre>`:e.args?.path?`<pre>${esc(e.args.path)}</pre>`:''}${e.error?`<p>${esc(e.error)}</p>`:''}</div>`).join('')||'<div class="tool-event pending">Ожидаю ответ локального бэкенда…</div>';
}
function resultTable(rows){if(!Array.isArray(rows)||!rows.length)return '<p class="empty-state">Результат не содержит строк.</p>';const columns=Object.keys(rows[0]);return `<div class="table-scroll sql-results"><table><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,50).map(r=>`<tr>${columns.map(c=>`<td>${esc(typeof r[c]==='object'?JSON.stringify(r[c]):r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length>50?'<p class="fine-print">Показаны первые 50 строк результата.</p>':''}</div>`;}
async function configureLocal(){
 if(!serverMode)return toast('Запустите локальную версию: ./start.command');const c=local.config;
 modal('Локальный workspace и SQLite',`<form id="local-config-form"><label class="form-label">Абсолютный путь рабочей папки<input name="workspace" value="${esc(c.workspace)}" required></label><label class="form-label">Путь SQLite внутри папки (можно оставить пустым для файлов)<input name="database" value="${esc(c.database)}" placeholder="company.sqlite"></label><div class="form-two even"><label class="form-label">Источник финансов<select name="sourceType"><option value="db" ${c.source.type==='db'?'selected':''}>SQLite-таблица</option><option value="file" ${c.source.type==='file'?'selected':''}>Локальный файл</option></select></label><label class="form-label">Таблица (пусто = определить по схеме)<input name="table" value="${esc(c.source.table)}" placeholder="sales"></label></div><label class="form-label">Финансовый файл, если выбран источник «Локальный файл»<input name="sourcePath" value="${esc(c.source.path)}" placeholder="finance/sales.xlsx"></label><details class="mapping-details"><summary>Соответствие колонок (пусто = авто)</summary><div class="mapping-grid">${['date','revenue','cost','product','category','channel'].map(k=>`<label class="form-label">${k}<input name="map-${k}" value="${esc(c.source.mapping?.[k])}" placeholder="${k}"></label>`).join('')}</div><label class="form-label">Лист Excel (пусто = первый)<input name="sheet" value="${esc(c.source.sheet)}"></label></details><label class="form-label">HR-файл CSV / JSON / XLSX (пусто = таблица candidates)<input name="hrFile" value="${esc(c.hrFile)}" placeholder="hr/candidates.json"></label><label class="form-label">JSON-файл диалогов<input name="messagesFile" value="${esc(c.messagesFile)}" placeholder="communications/threads.json"></label><label class="form-label">Локальная Ollama-модель (необязательно)<input name="model" value="${esc(c.model)}" placeholder="Имя установленной модели с tool calling"></label><p class="fine-print">SQLite: только SELECT. Пути файлов относительны workspace. Настройки действуют до перезапуска сервера; для постоянного подключения используйте ORBIT_WORKSPACE и ORBIT_DB.</p><div class="modal-error" id="config-error" role="alert"></div><div class="modal-actions"><button class="btn dark" type="submit">Подключить и перечитать ${icon('right')}</button></div></form>`,()=>{$('#local-config-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),mapping={};for(const k of ['date','revenue','cost','product','category','channel'])if(d.get('map-'+k).trim())mapping[k]=d.get('map-'+k).trim();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('/api/config',{workspace:d.get('workspace').trim(),database:d.get('database').trim(),hrFile:d.get('hrFile').trim(),messagesFile:d.get('messagesFile').trim(),model:d.get('model').trim(),source:{type:d.get('sourceType'),table:d.get('table').trim(),path:d.get('sourcePath').trim(),sheet:d.get('sheet').trim(),mapping}});state.runs=[];state.plan=[];state.shortlisted=[];await refreshLocal();closeModal();toast('Локальный контекст подключён.');}catch(error){$('#config-error').textContent=error.message;}finally{button.disabled=false;}};});
}
async function workspaceBrowser(){try{
 if(!serverMode)throw Error('Запустите локальную версию Orbit.');const list=await api('/api/workspace/files');local.files=list.files;
 modal('Файлы рабочей папки',`<p class="modal-intro path-value">${esc(local.config.workspace)}</p><div class="workspace-files">${list.files.map(f=>`<div class="workspace-file"><span class="connection-icon">${icon(/db|sqlite/.test(f.format)?'database':'file')}</span><div><strong>${esc(f.path)}</strong><small>${f.format.toUpperCase()} · ${Math.ceil(f.size/1024)} КБ</small></div>${['csv','json','xlsx','txt','md'].includes(f.format)?`<button class="btn small-btn" data-read-local="${esc(f.path)}">Читать</button>`:'<span class="pill">База</span>'}${['csv','json','xlsx'].includes(f.format)?`<button class="btn small-btn" data-select-local="${esc(f.path)}">Выбрать</button>`:''}</div>`).join('')||'<p>Поддерживаемых файлов не найдено.</p>'}</div>${list.truncated?'<p class="fine-print">Показаны первые 500 файлов.</p>':''}<div class="modal-actions"><button class="btn" id="change-root">Изменить папку</button></div>`,()=>{
 $('#change-root').onclick=()=>{closeModal();configureLocal();};
 document.querySelectorAll('[data-read-local]').forEach(b=>b.onclick=async()=>{try{const f=await api('/api/tools/read_workspace_file',{path:b.dataset.readLocal});modal(esc(f.path),f.records?resultTable(f.records):`<pre class="file-preview">${esc(f.text||JSON.stringify(f.data,null,2))}</pre>`);}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-select-local]').forEach(b=>b.onclick=()=>selectWorkspaceFile(b.dataset.selectLocal));
 });
 }catch(e){toast(e.message);}}
function selectWorkspaceFile(path){modal('Использовать локальный файл',`<p class="modal-intro path-value">${esc(path)}</p><p>Выберите назначение. Файл остаётся на диске и будет перечитываться сервером.</p><div class="source-choices"><button class="btn" id="use-finance">${icon('chart')} Финансовая аналитика</button><button class="btn" id="use-hr">${icon('users')} HR-резюме</button><button class="btn" id="use-threads">${icon('chat')} Диалоги (JSON)</button></div><div class="modal-error" id="selection-error" role="alert"></div>`,()=>{for(const [id,body,view] of [['use-finance',{source:{type:'file',path}},'analytics'],['use-hr',{hrFile:path},'hr'],['use-threads',{messagesFile:path},'messages']])$('#'+id).onclick=async()=>{try{await api('/api/config',body);state.period='latest';const context=await refreshLocal();if(context.errors.length)throw Error(context.errors.join(' '));closeModal();go(view);toast('Источник подключён: '+path);}catch(e){$('#selection-error').textContent=e.message;}};});}
async function schemaDialog(){try{
 if(!serverMode)throw Error('Запустите локальную версию Orbit.');const schema=await api('/api/tools/get_db_schema',{});local.schema=schema;
 modal('SQLite · схема и SELECT',`<div class="schema-list">${schema.tables.map(t=>`<details><summary>${icon('database')} ${esc(t.name)} <small>${t.columns.length} полей · ${esc(t.type)}</small></summary><div class="schema-columns">${t.columns.map(c=>`<span><strong>${esc(c.name)}</strong> ${esc(c.type)} ${c.primaryKey?'· PK':''}</span>`).join('')}</div></details>`).join('')||'<p>Таблиц не найдено.</p>'}</div><label class="form-label">SQL-запрос (только SELECT)<textarea id="sql-input" rows="4" spellcheck="false">SELECT * FROM "${esc((schema.tables[0]?.name||'sales').replaceAll('"','""'))}" LIMIT 20</textarea></label><div class="modal-actions"><button class="btn dark" id="run-sql">${icon('right')} Выполнить SELECT</button></div><div class="modal-error" id="sql-error" role="alert"></div><div id="sql-output"></div>`,()=>{$('#run-sql').onclick=async()=>{const button=$('#run-sql');button.disabled=true;$('#sql-error').textContent='';try{const r=await api('/api/tools/execute_sql_query',{query:$('#sql-input').value});$('#sql-output').innerHTML=`<p class="fine-print">${r.rowCount} строк · ${r.elapsedMs} ms · ${r.truncated?'результат ограничен':'Read-only'}</p>${resultTable(r.rows)}`;}catch(e){$('#sql-error').textContent=e.message;$('#sql-output').innerHTML='';}finally{button.disabled=false;}};});
 }catch(e){toast(e.message);}}
